/**
 * Ads Reports Routes
 * Serve HTML reports generated by notebooks
 * Single Responsibility: Serve static HTML reports
 */

import { Router, Request, Response } from "express";
import { promises as fs } from "fs";
import path from "path";
import { getLogger } from "../utils/logger";

const router = Router();
const logger = getLogger("AdsReportsRoutes");

// Reports directory paths (will be mounted via Docker volume)
const REPORTS_DIR = process.env.REPORTS_DIR || "/app/reports";
const SHOPEE_REPORTS_DIR = path.join(REPORTS_DIR, "shopee");
const TIKTOK_REPORTS_DIR = path.join(REPORTS_DIR, "tiktok");

interface ReportInfo {
  filename: string;
  type: "full" | "executive";
  platform: "shopee" | "tiktok";
  period: string;
  createdAt: Date;
  size: number;
}

/**
 * Parse report filename to extract info
 * Format: SHOPEE_ADS_REPORT_Q1_2026_20260117_0910.html
 *         TIKTOK_ADS_REPORT_Q1_2026_20260117_0910_EXECUTIVE.html
 */
function parseReportFilename(
  filename: string,
  platform: "shopee" | "tiktok",
): Partial<ReportInfo> {
  const isExecutive = filename.includes("_EXECUTIVE");
  const type = isExecutive ? "executive" : "full";

  // Extract period (Q1_2026 or similar)
  const periodMatch = filename.match(/_(Q\d+_\d{4}|FULL)_/);
  const period = periodMatch ? periodMatch[1] : "Unknown";

  return { filename, type, platform, period };
}

/**
 * List reports in a directory
 */
async function listReports(
  dir: string,
  platform: "shopee" | "tiktok",
): Promise<ReportInfo[]> {
  try {
    const files = await fs.readdir(dir);
    const htmlFiles = files.filter((f) => f.endsWith(".html"));

    const reports: ReportInfo[] = [];
    for (const filename of htmlFiles) {
      const stat = await fs.stat(path.join(dir, filename));
      const info = parseReportFilename(filename, platform);
      reports.push({
        ...info,
        filename,
        platform,
        type: info.type || "full",
        period: info.period || "Unknown",
        createdAt: stat.mtime,
        size: stat.size,
      });
    }

    // Sort by createdAt desc
    return reports.sort(
      (a, b) => b.createdAt.getTime() - a.createdAt.getTime(),
    );
  } catch (error) {
    logger.warn(`Failed to list reports in ${dir}`, { error });
    return [];
  }
}

/**
 * GET /api/reports/shopee/list
 * List all Shopee Ads reports
 */
router.get("/shopee/list", async (_req: Request, res: Response) => {
  try {
    const reports = await listReports(SHOPEE_REPORTS_DIR, "shopee");
    res.json({ success: true, data: reports });
  } catch (error) {
    res.status(500).json({ success: false, error: "Failed to list reports" });
  }
});

/**
 * GET /api/reports/shopee/latest
 * Get latest Shopee report (full or executive)
 */
router.get("/shopee/latest", async (req: Request, res: Response) => {
  try {
    const type = (req.query.type as "full" | "executive") || "full";
    const reports = await listReports(SHOPEE_REPORTS_DIR, "shopee");
    const filtered = reports.filter((r) => r.type === type);

    if (filtered.length === 0) {
      res.status(404).json({ success: false, error: "No reports found" });
      return;
    }

    const latest = filtered[0];
    const filePath = path.join(SHOPEE_REPORTS_DIR, latest.filename);
    const content = await fs.readFile(filePath, "utf-8");

    res.setHeader("Content-Type", "text/html");
    res.send(content);
  } catch (error) {
    logger.error("Failed to get latest Shopee report", { error });
    res.status(500).json({ success: false, error: "Failed to get report" });
  }
});

/**
 * GET /api/reports/shopee/:filename
 * Get specific Shopee report by filename
 */
router.get("/shopee/:filename", async (req: Request, res: Response) => {
  try {
    const { filename } = req.params;
    // Security: prevent directory traversal
    const safeName = path.basename(filename);
    const filePath = path.join(SHOPEE_REPORTS_DIR, safeName);

    const content = await fs.readFile(filePath, "utf-8");
    res.setHeader("Content-Type", "text/html");
    res.send(content);
  } catch (error) {
    res.status(404).json({ success: false, error: "Report not found" });
  }
});

